document.addEventListener("DOMContentLoaded",()=>{const e=window.matchMedia("(prefers-reduced-motion: reduce)").matches;document.querySelectorAll(".cross-section a[href^='#']").forEach(t=>{t.addEventListener("click",o=>{const r=t.getAttribute("href").slice(1),s=document.getElementById(r);s&&(o.preventDefault(),s.scrollIntoView({behavior:e?"auto":"smooth",block:"start"}),s.setAttribute("tabindex","-1"),s.focus({preventScroll:!0}))})});const t=["airport","reefs","beaches","water-sports","marine-life","tourism"],o=t.map(e=>({id:e,seg:document.querySelector(`.cross-section a[href="#${e}"] .cross-section-seg`)})).filter(e=>e.seg);if("IntersectionObserver"in window&&o.length){const e=new IntersectionObserver(e=>{e.forEach(e=>{const t=o.find(t=>t.id===e.target.id);t&&(t.seg.style.opacity=e.isIntersecting?"1":"0.62")})},{threshold:.35});t.forEach(t=>{const o=document.getElementById(t);o&&e.observe(o)})}});